// app/api/quotes/[token]/items/route.js
import { NextResponse } from "next/server";

/**
 * Assumes these Airtable labels (change the strings below if yours differ):
 * Tables:
 *   - "Quote Requests"
 *   - "Quote Line Items"
 *   - "Pricing Rules"
 * Fields:
 *   - On Quote Requests: "Token", "Stories (cache)", "Square Footage (cache)", "Lot Size (cache)"
 *   - On Quote Line Items: "Quote Request" (link), "Service" (single-select),
 *       "Chosen Frequency" (single-select), "Suggested Frequency" (single-select),
 *       "Pricing Rule" (link), (optional) "Notes"
 *   - On Pricing Rules: "Lookup Key"
 *
 * Behavior:
 *   1) Create line item linked to Quote Request, set Service + Frequency (single-selects).
 *   2) Read the quote’s cached values and build the pricing lookup key:
 *        `${service} | ${stories} | ${sqft} | ${lot}`
 *   3) Find the Pricing Rules row by Lookup Key and link it to the new line item.
 *   4) If no frequency was provided, set Chosen Frequency = Suggested Frequency.
 *   5) Return created row + whether Pricing Rule was linked.
 */

const AIRTABLE_API_KEY = process.env.AIRTABLE_API_KEY;
const AIRTABLE_BASE_ID = process.env.AIRTABLE_BASE_ID;

// ----- Table names (edit if your labels differ) -----
const QUOTES_TABLE        = process.env.AIRTABLE_TABLE_QUOTES         || "Quote Requests";
const LINE_ITEMS_TABLE    = process.env.AIRTABLE_TABLE_LINE_ITEMS     || "Quote Line Items";
const PRICING_RULES_TABLE = process.env.AIRTABLE_TABLE_PRICING_RULES  || "Pricing Rules";

// ----- Field names (edit if your labels differ) -----
const QUOTE_TOKEN_FIELD     = process.env.AIRTABLE_FIELD_TOKEN                || "Token";
const QUOTE_STORIES_FIELD   = process.env.AIRTABLE_FIELD_QUOTE_STORIES        || "Stories (cache)";
const QUOTE_SQFT_FIELD      = process.env.AIRTABLE_FIELD_QUOTE_SQFT           || "Square Footage (cache)";
const QUOTE_LOTSIZE_FIELD   = process.env.AIRTABLE_FIELD_QUOTE_LOTSIZE        || "Lot Size (cache)";

const LI_LINK_TO_QUOTE      = process.env.AIRTABLE_FIELD_LI_QUOTE             || "Quote Request";
const LI_SERVICE_FIELD      = process.env.AIRTABLE_FIELD_LI_SERVICE           || "Service";               // single-select
const LI_CHOSEN_FREQ_FIELD  = process.env.AIRTABLE_FIELD_LI_CHOSEN_FREQ       || "Chosen Frequency";     // single-select
const LI_SUGGESTED_FREQ_FLD = process.env.AIRTABLE_FIELD_LI_SUGGESTED_FREQ    || "Suggested Frequency";  // single-select (or lookup)
const LI_PRICING_RULE_FIELD = process.env.AIRTABLE_FIELD_LI_PRICING_RULE      || "Pricing Rule";         // link
const LI_NOTES_FIELD        = process.env.AIRTABLE_FIELD_LI_NOTES             || "Notes";                // optional

const PR_LOOKUP_KEY_FIELD   = process.env.AIRTABLE_FIELD_PR_LOOKUP_KEY        || "Lookup Key";

function bad(status, msg) {
  return NextResponse.json({ error: msg }, { status });
}

async function at(path, options = {}) {
  const res = await fetch(`https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/${path}`, {
    ...options,
    headers: {
      Authorization: `Bearer ${AIRTABLE_API_KEY}`,
      "Content-Type": "application/json",
      ...(options.headers || {}),
    },
  });
  const data = await res.json();
  return { ok: res.ok, status: res.status, data };
}

// Resolve Quote Request record id by token
async function quoteIdFromToken(token) {
  const filter = encodeURIComponent(`{${QUOTE_TOKEN_FIELD}} = "${token}"`);
  const { ok, status, data } = await at(
    `${encodeURIComponent(QUOTES_TABLE)}?filterByFormula=${filter}&maxRecords=1`
  );
  if (!ok) throw new Error(`Airtable ${status}: ${data?.error?.message || "Quote lookup failed"}`);
  return data?.records?.[0]?.id || null;
}

// Read caches from Quote Request (Stories/SqFt/Lot)
async function fetchQuoteCaches(quoteId) {
  const { ok, status, data } = await at(`${encodeURIComponent(QUOTES_TABLE)}/${quoteId}`);
  if (!ok) throw new Error(`Airtable ${status}: ${data?.error?.message || "Quote read failed"}`);
  const f = data?.fields || {};
  return {
    stories: f[QUOTE_STORIES_FIELD] ?? "Any",
    sqft:    f[QUOTE_SQFT_FIELD]    ?? "Any",
    lot:     f[QUOTE_LOTSIZE_FIELD] ?? "Any",
  };
}

function buildLookupKey(service, caches) {
  // mirrors your Airtable formula for Lookup Key (cache)
  return `${service} | ${caches.stories} | ${caches.sqft} | ${caches.lot}`;
}

async function findPricingRuleIdByLookupKey(lookupKey) {
  const filter = encodeURIComponent(`{${PR_LOOKUP_KEY_FIELD}} = "${lookupKey}"`);
  const { ok, status, data } = await at(
    `${encodeURIComponent(PRICING_RULES_TABLE)}?filterByFormula=${filter}&maxRecords=1`
  );
  if (!ok) throw new Error(`Airtable ${status}: ${data?.error?.message || "Pricing Rules query failed"}`);
  return data?.records?.[0]?.id || null;
}

// Normalize a Suggested Frequency value that might be string/object/array
function normalizeSuggested(val) {
  if (!val) return null;
  if (typeof val === "string") return val;
  if (Array.isArray(val)) {
    // lookups sometimes return arrays—take first stringy thing
    const first = val[0];
    if (!first) return null;
    if (typeof first === "string") return first;
    if (typeof first === "object" && first.name) return first.name;
    return null;
  }
  if (typeof val === "object" && val.name) return val.name;
  return null;
}

export async function POST(req, { params }) {
  try {
    if (!AIRTABLE_API_KEY || !AIRTABLE_BASE_ID) return bad(500, "Missing Airtable credentials");

    const tokenFromUrl = params?.token;
    const body = await req.json().catch(() => ({}));

    // Expected body:
    // { serviceName: "Gutter Cleaning", frequency?: "Monthly", useSuggested?: boolean, notes?: string, quoteRecordId?: "rec..." }
    const serviceName = body?.serviceName || body?.service;
    if (!serviceName) return bad(400, "Missing serviceName");

    // Determine target quote
    let quoteId = body?.quoteRecordId || null;
    if (!quoteId) {
      if (!tokenFromUrl) return bad(400, "Missing quoteRecordId and URL token");
      quoteId = await quoteIdFromToken(tokenFromUrl);
      if (!quoteId) return bad(400, "Could not resolve quoteRecordId from token");
    }

    const frequency    = body?.frequency || null;
    const useSuggested = Boolean(body?.useSuggested);
    const notes        = body?.notes ?? undefined;

    // 1) CREATE line item (Service & Frequency are SINGLE-SELECTS → pass plain strings)
    const createFields = {
      [LI_LINK_TO_QUOTE]: [quoteId],     // link field expects array of record IDs
      [LI_SERVICE_FIELD]: serviceName,   // single-select → string (typecast true)
    };
    if (frequency) {
      const freqField = useSuggested ? LI_SUGGESTED_FREQ_FLD : LI_CHOSEN_FREQ_FIELD;
      createFields[freqField] = frequency; // single-select → string (typecast true)
    }
    if (notes) createFields[LI_NOTES_FIELD] = notes;

    const createPayload = { records: [{ fields: createFields }], typecast: true };
    const createRes = await at(`${encodeURIComponent(LINE_ITEMS_TABLE)}`, {
      method: "POST",
      body: JSON.stringify(createPayload),
    });
    if (!createRes.ok) {
      return bad(createRes.status, createRes.data?.error?.message || "Airtable create error");
    }
    const created = createRes.data.records?.[0];
    const lineItemId = created?.id;

    // 2) Read quote caches and compute lookup key
    const caches = await fetchQuoteCaches(quoteId);
    const lookupKey = buildLookupKey(serviceName, caches);

    // 3) Find matching Pricing Rule and link it to the line item
    const pricingRuleId = await findPricingRuleIdByLookupKey(lookupKey);
    let pricingRuleLinked = false;

    if (pricingRuleId && lineItemId) {
      const patchPayload = {
        records: [{ id: lineItemId, fields: { [LI_PRICING_RULE_FIELD]: [pricingRuleId] } }],
        typecast: true,
      };
      const patchRes = await at(`${encodeURIComponent(LINE_ITEMS_TABLE)}`, {
        method: "PATCH",
        body: JSON.stringify(patchPayload),
      });
      pricingRuleLinked = patchRes.ok;

      // 4) NEW: if no frequency provided, set Chosen Frequency = Suggested Frequency
      if (!frequency && pricingRuleLinked) {
        // refetch line item so Suggested Frequency (possibly a lookup) is populated
        const readRes = await at(`${encodeURIComponent(LINE_ITEMS_TABLE)}/${lineItemId}`);
        if (readRes.ok) {
          const suggestedRaw = readRes.data?.fields?.[LI_SUGGESTED_FREQ_FLD];
          const suggested = normalizeSuggested(suggestedRaw);
          if (suggested) {
            await at(`${encodeURIComponent(LINE_ITEMS_TABLE)}`, {
              method: "PATCH",
              body: JSON.stringify({
                records: [{ id: lineItemId, fields: { [LI_CHOSEN_FREQ_FIELD]: suggested } }],
                typecast: true,
              }),
            });
          }
        }
      }
    }

    return NextResponse.json(
      { ok: true, created, lookupKey, pricingRuleLinked },
      { status: 201 }
    );
  } catch (err) {
    console.error(err);
    return bad(500, "Unexpected server error");
  }
}

