import { 
  Droplets, 
  Sparkles, 
  Scissors, 
  Waves, 
  Shovel, 
  TreePine,
  Hammer,
  Car,
  Home,
  Wrench,
  Leaf,
  Sun
} from 'lucide-react';
import { LucideIcon } from 'lucide-react';

export interface ServiceIconProps {
  className?: string;
}

/**
 * Maps service names to appropriate Lucide React icons
 */
export function getServiceIcon(serviceName: string): LucideIcon {
  const service = serviceName.toLowerCase();

  // Window cleaning services
  if (service.includes('window')) {
    return Sparkles;
  }

  // Gutter cleaning services
  if (service.includes('gutter')) {
