import { 
  Droplets, 
  Sparkles, 
  Scissors, 
  Waves, 
  Shovel, 
  TreePine,
  Hammer,
  Car,
  Home,
  Wrench,
  Leaf,
  Sun
} from 'lucide-react';
import { LucideIcon } from 'lucide-react';

export interface ServiceIconProps {
  className?: string;
}

/**
 * Maps service names to appropriate Lucide React icons
 */
export function getServiceIcon(serviceName: string): LucideIcon {
  const service = serviceName.toLowerCase();

  // Window cleaning services
  if (service.includes('window')) {
    return Sparkles;
  }

  // Gutter cleaning services
  if (service.includes('gutter')) {
    return Droplets;
  }

  // Lawn care and mowing services
  if (service.includes('lawn') || service.includes('mowing') || service.includes('grass')) {
    return Scissors;
  }

  // Pressure washing services
  if (service.includes('pressure') || service.includes('power wash')) {
    return Waves;
  }

  // Pool services
  if (service.includes('pool')) {
    return Waves;
  }

  // Tree services
  if (service.includes('tree') || service.includes('trimming') || service.includes('pruning')) {
    return TreePine;
  }

  // Landscaping and gardening
  if (service.includes('landscape') || service.includes('garden') || service.includes('planting')) {
    return Leaf;
  }

  // Driveway and patio services
  if (service.includes('driveway') || service.includes('patio') || service.includes('deck')) {
    return Car;
  }

  // General handyman services
  if (service.includes('handyman') || service.includes('repair') || service.includes('fix')) {
    return Hammer;
  }

  // Snow services
  if (service.includes('snow') || service.includes('ice')) {
    return Shovel;
  }

  // Roofing services
  if (service.includes('roof') || service.includes('gutter')) {
    return Home;
  }

  // HVAC and plumbing
  if (service.includes('hvac') || service.includes('plumb') || service.includes('air')) {
    return Wrench;
  }

  // Solar and electrical
  if (service.includes('solar') || service.includes('electric')) {
    return Sun;
  }

  // Default icon for unrecognized services
  return Wrench;
}

/**
 * ServiceIcon component that displays the appropriate icon for a service
 */
export function ServiceIcon({ serviceName, className = "h-4 w-4" }: { 
  serviceName: string; 
  className?: string; 
}) {
  const IconComponent = getServiceIcon(serviceName);
  return <IconComponent className={className} />;
}

