// app/api/services/route.js
import { NextResponse } from 'next/server';
export const dynamic = 'force-dynamic';

const atBase = () => process.env.AIRTABLE_BASE_ID;
const atKey  = () => process.env.AIRTABLE_API_KEY;
const tblPR  = () => process.env.AIRTABLE_TABLE_PRICING_RULES || 'Pricing Rules';

// Strict allowlist to match your Line Items single-select options
const ALLOWED = new Set([
  'Window Washing',
  'Gutter Cleaning',
  'Pressure Washing - Driveway & Patio',
  'Pressure Washing - Home Exterior',
  'Pest Control',
  'Trash Bin Cleaning',
  'Handyman',
]);

async function ats(url, init) {
  const res = await fetch(url, {
    ...init,
    headers: { Authorization: `Bearer ${atKey()}`, 'Content-Type': 'application/json', ...(init?.headers||{}) },
    cache: 'no-store',
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`Airtable ${res.status}: ${text}`);
  return text ? JSON.parse(text) : {};
}

export async function GET() {
  try {
    const base = atBase(), rules = tblPR();
    const url = `https://api.airtable.com/v0/${base}/${encodeURIComponent(rules)}?pageSize=100&fields[]=Service`;
    const data = await ats(url);
    const names = new Set();
    (data.records || []).forEach(r => {
      const name = r?.fields?.Service;
      if (name && ALLOWED.has(String(name))) names.add(String(name));
    });
    return NextResponse.json({ services: Array.from(names).sort() });
  } catch (e) {
    return NextResponse.json({ error: e?.message || 'failed' }, { status: 500 });
  }
}

