  }

  if (service === 'pest control') {
    return 'Zap ⚡';
  }

  if (service === 'trash bin cleaning') {
    return 'Sparkles ✨';
  }

  if (service === 'handyman') {
    return 'Hammer 🔨';
  }

  // Fallback keyword matching
  if (service.includes('window')) return 'Sparkles ✨';
  if (service.includes('gutter')) return 'Droplets 💧';
