 */
export function getServiceIcon(serviceName: string): LucideIcon {
  const service = serviceName.toLowerCase();

  // Exact matches first for better accuracy
  if (service === 'window washing') {
    return Sparkles;
  }

  if (service === 'gutter cleaning') {
    return Droplets;
  }

  if (service === 'pressure washing - driveway & patio') {
    return Car; // driveway/patio icon
  }

  if (service === 'pressure washing - home exterior') {
    return Waves; // water/washing icon
  }

  if (service === 'pest control') {
    return Zap; // pest control icon
  }

  if (service === 'trash bin cleaning') {
    return Sparkles; // cleaning icon
  }

  if (service === 'handyman') {
    return Hammer;
  }

  // Fallback to keyword matching for any other services
  if (service.includes('window')) {
    return Sparkles;
  }

  if (service.includes('gutter')) {
    return Droplets;
  }

  if (service.includes('pressure')) {
    return Waves;
  }

  if (service.includes('pest')) {
    return Zap;
  }

  if (service.includes('trash') || service.includes('bin')) {
    return Sparkles;
  }

  if (service.includes('handyman')) {
    return Hammer;
  }

  // Lawn care and mowing services
  if (service.includes('lawn') || service.includes('mowing') || service.includes('grass')) {
    return Scissors;
  }

  // Pool services
  if (service.includes('pool')) {
    return Waves;
  }

  // Tree services
  if (service.includes('tree') || service.includes('trimming') || service.includes('pruning')) {
    return TreePine;
  }

  // Landscaping and gardening
  if (service.includes('landscape') || service.includes('garden') || service.includes('planting')) {
    return Leaf;
  }

  // Driveway and patio services
  if (service.includes('driveway') || service.includes('patio') || service.includes('deck')) {
    return Car;
  }

  // Snow services
  if (service.includes('snow') || service.includes('ice')) {
    return Shovel;
  }

  // Roofing services
  if (service.includes('roof')) {
    return Home;
  }

  // HVAC and plumbing
  if (service.includes('hvac') || service.includes('plumb') || service.includes('air')) {
    return Wrench;
  }

  console.log('No specific match found for:', serviceName, '- using default Wrench icon');

